using Filedock.Core.V1;
using FileDock.Management.Api.Auth;
using FileDock.Management.Api.Infrastructure;
using FileDock.Management.Core;
using FileDock.Management.Domain.Audit;
namespace FileDock.Management.Api.Endpoints;

public static class StorageEndpoints
{
    public sealed record PressureInput(uint WarningPercent, uint CriticalPercent);
    public sealed record PoolInput(string Name, string[] DiskSerials, string TypedConfirmation);
    public sealed record AdoptInput(string Name, string DiskSerial);
    public sealed record ExtendInput(string DiskSerial, string TypedConfirmation);
    public sealed record LimitsInput(uint MaxUsagePercent, ulong ReservedFreeGb, bool AcknowledgedInterruption = false);
    private static async Task<IResult> Operation(Func<Task<Operation>> action, HttpContext c, AuditWriter audit, string kind) { var op = await action(); await ObservabilityEndpoints.Audit(c, audit, kind, op.Id); return Results.Accepted($"/api/v1/operations/{op.Id}", CoreClient.ToOperation(op)); }
    public static void MapStorage(this RouteGroupBuilder api)
    {
        api.MapGet("/system/storage-settings", (CoreClient core, HttpContext c) => ObservabilityEndpoints.Run(async () => { var row = await core.Control.GetResourceAsync(new ResourceRef { Kind = ResourceKind.Settings, Id = "default" }, ObservabilityEndpoints.Headers(c, false)); var spec = ResourceEndpoints.Json(row.Spec); return Results.Ok(new { row.Generation, warningPercent = spec.TryGetProperty("diskPressureWarningPercent", out var w) ? w.GetUInt32() : 90u, criticalPercent = spec.TryGetProperty("diskPressureCriticalPercent", out var n) ? n.GetUInt32() : 95u }); })).WithMetadata(new AccessScope("R"));
        api.MapPut("/system/storage-settings", (PressureInput body, CoreClient core, HttpContext c, AuditWriter audit) => ObservabilityEndpoints.Run(async () => { var row = await core.Control.GetResourceAsync(new ResourceRef { Kind = ResourceKind.Settings, Id = "default" }, ObservabilityEndpoints.Headers(c, false)); var spec = System.Text.Json.Nodes.JsonNode.Parse(ResourceEndpoints.Json(row.Spec).GetRawText())!.AsObject(); spec["diskPressureWarningPercent"] = body.WarningPercent; spec["diskPressureCriticalPercent"] = body.CriticalPercent; var saved = await ResourceEndpoints.Save(core, c, ResourceKind.Settings, "default", spec); await ObservabilityEndpoints.Audit(c, audit, "storage.alert-thresholds.changed", "appliance"); return Results.Ok(new { saved.Generation }); })).WithMetadata(new AccessScope("S"));
        api.MapGet("/disks", (CoreClient core, HttpContext c) => ObservabilityEndpoints.Run(async () => Results.Ok(new { items = (await core.Storage.ListDisksAsync(new ListDisksRequest(), ObservabilityEndpoints.Headers(c, false))).Disks.Select(d => new { d.Serial, d.Wwn, d.Model, d.SizeBytes, d.DevicePath, d.IsSystemDisk, d.IsBlank, d.ExistingFilesystem, d.PoolId, health = d.Health.ToString() }) }))).WithMetadata(new AccessScope("R"));
        api.MapGet("/pools/system", (CoreClient core, HttpContext c) => ObservabilityEndpoints.Run(async () => { var view = await core.Storage.GetSystemPoolAsync(new Empty(), ObservabilityEndpoints.Headers(c, false)); Concurrency.SetGeneration(c.Response, (long)view.Generation); return Results.Ok(ResourceEndpoints.Json(view)); })).WithMetadata(new AccessScope("R"));
        api.MapPut("/pools/system/limits", (LimitsInput body, CoreClient core, HttpContext c, AuditWriter audit) => ObservabilityEndpoints.Run(async () => { var g = Concurrency.IfMatch(c.Request); if (g is null || g < 1) { return Results.Problem(statusCode: 428, detail: "Supply If-Match with the current generation."); } if (body.ReservedFreeGb > ulong.MaxValue / 1_000_000_000) { return Results.Problem(statusCode: 422, detail: "system_pool.reserve_invalid"); } return await Operation(async () => await core.Storage.SetSystemPoolLimitsAsync(new SetSystemPoolLimitsRequest { MaxUsagePercent = body.MaxUsagePercent, ReservedFreeBytes = body.ReservedFreeGb * 1_000_000_000, ExpectedGeneration = (ulong)g, AcknowledgedInterruption = body.AcknowledgedInterruption }, ObservabilityEndpoints.Headers(c, true)), c, audit, "system-pool.limits.changed"); })).WithMetadata(new AccessScope("S"));
        api.MapGet("/pools", (CoreClient core, HttpContext c) => ObservabilityEndpoints.Run(() => ResourceEndpoints.Page(core, ResourceKind.Pool, c))).WithMetadata(new AccessScope("R"));
        api.MapGet("/pools/{id}", (string id, CoreClient core, HttpContext c) => ObservabilityEndpoints.Run(async () => { var row = await core.Control.GetResourceAsync(new ResourceRef { Kind = ResourceKind.Pool, Id = id }, ObservabilityEndpoints.Headers(c, false)); Concurrency.SetGeneration(c.Response, (long)row.Generation); return Results.Ok(ResourceEndpoints.View(row)); })).WithMetadata(new AccessScope("R"));
        api.MapPost("/pools", (PoolInput body, CoreClient core, HttpContext c, AuditWriter audit) => ObservabilityEndpoints.Run(() => Operation(async () => await core.Storage.CreatePoolAsync(new CreatePoolRequest { Name = body.Name, DiskSerials = { body.DiskSerials }, TypedConfirmation = body.TypedConfirmation }, ObservabilityEndpoints.Headers(c, true)), c, audit, "pool.create"))).WithMetadata(new AccessScope("F"));
        api.MapPost("/pools/adopt", (AdoptInput body, CoreClient core, HttpContext c, AuditWriter audit) => ObservabilityEndpoints.Run(() => Operation(async () => await core.Storage.AdoptFilesystemAsync(new AdoptFilesystemRequest { Name = body.Name, DiskSerial = body.DiskSerial }, ObservabilityEndpoints.Headers(c, true)), c, audit, "pool.adopt"))).WithMetadata(new AccessScope("F"));
        api.MapPost("/pools/{id}/disks", (string id, ExtendInput body, CoreClient core, HttpContext c, AuditWriter audit) => ObservabilityEndpoints.Run(() => Operation(async () => await core.Storage.ExtendPoolAsync(new ExtendPoolRequest { PoolId = id, DiskSerial = body.DiskSerial, TypedConfirmation = body.TypedConfirmation }, ObservabilityEndpoints.Headers(c, true)), c, audit, "pool.extend"))).WithMetadata(new AccessScope("F"));
        api.MapPost("/pools/{id}/recreate", (string id, PoolInput body, CoreClient core, HttpContext c, AuditWriter audit) => ObservabilityEndpoints.Run(() => Operation(async () => await core.Storage.RecreatePoolAsync(new RecreatePoolRequest { PoolId = id, DiskSerials = { body.DiskSerials }, TypedConfirmation = body.TypedConfirmation }, ObservabilityEndpoints.Headers(c, true)), c, audit, "pool.recreate"))).WithMetadata(new AccessScope("F"));
        api.MapDelete("/pools/{id}", (string id, CoreClient core, HttpContext c, AuditWriter audit) => ObservabilityEndpoints.Run(() => ResourceEndpoints.Delete(core, c, audit, ResourceKind.Pool, id))).WithMetadata(new AccessScope("F"));
    }
}
